import { mkdir, readFile, rm, stat, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';

/**
 * Where attachment contents live. Keys are "<institution id>/<file id>" (both UUIDs, generated by the
 * server): user input never reaches a path or an object name.
 */
export type StorageBackend = 'local' | 's3';

export interface BlobStore {
  readonly backend: StorageBackend;
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer>;
  remove(key: string): Promise<void>;
  /** Throws when the store cannot be used (for the readiness check). */
  probe(): Promise<void>;
}

const KEY = /^[0-9a-f-]{36}\/[0-9a-f-]{36}$/;
export function assertKey(key: string) {
  if (!KEY.test(key)) throw new Error('Chave de anexo inválida');
}
export const blobKey = (institutionId: string, fileId: string) => {
  const key = `${institutionId}/${fileId}`;
  assertKey(key);
  return key;
};

/** Files on a local directory outside the web root (directories 700, files 600, never overwritten). */
export class LocalDiskStore implements BlobStore {
  readonly backend = 'local' as const;
  private readonly root: string;
  constructor(dir: string) {
    this.root = resolve(dir);
  }

  private path(key: string) {
    assertKey(key);
    return join(this.root, ...key.split('/'));
  }

  async put(key: string, data: Buffer) {
    const path = this.path(key);
    await mkdir(join(this.root, key.split('/')[0]!), { recursive: true, mode: 0o700 });
    await writeFile(path, data, { mode: 0o600, flag: 'wx' });
  }

  get(key: string) {
    return readFile(this.path(key));
  }

  async remove(key: string) {
    await rm(this.path(key), { force: true });
  }

  async probe() {
    await mkdir(this.root, { recursive: true, mode: 0o700 });
    if (!(await stat(this.root)).isDirectory()) throw new Error('UPLOAD_DIR não é um diretório.');
  }
}
